"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant1 from "./components/flip-card/variants/02-modal";
const variants = { modal: Variant1 };
export interface ArtemisFlipCardProps {
  className?: string;
  variant?: "modal";
}
export function ArtemisFlipCard({ className, variant = "modal" }: ArtemisFlipCardProps) {
  const View = variants[variant];
  return (
    <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}>
      <View />
    </ArtemisScope>
  );
}

"use client";
// @zeus-internal
import { Dialog, DialogBackdrop, DialogPanel } from "../../../lib/headless";
import { AnimatePresence, motion, MotionConfig, useReducedMotion } from "motion/react";
import { useRef, useState } from "react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { Back, Close, Front } from "./02-modal/content";
type Rect = {
    left: number;
    top: number;
    width: number;
    height: number;
};
type Bounds = {
    origin: Rect;
    target: Rect;
};
const OPEN = { type: "spring", stiffness: 245, damping: 27, mass: 0.9 } as const;
const CLOSE = { type: "spring", stiffness: 285, damping: 30, mass: 0.86 } as const;
const SURFACE = "art:pointer-events-none art:relative art:z-20 art:h-full art:w-full art:[&_a]:pointer-events-auto art:[&_button]:pointer-events-auto";
const FLIP = "art:absolute art:inset-0 art:z-10 art:cursor-pointer art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-inset";
function measure(trigger: HTMLButtonElement): Bounds {
    const rect = trigger.getBoundingClientRect();
    const width = Math.min(window.innerWidth < 480 ? 320 : 352, window.innerWidth - 32, (window.innerHeight - 32) * 0.8);
    const height = width / 0.8;
    return {
        origin: { left: rect.left, top: rect.top, width: rect.width, height: rect.height },
        target: { left: (window.innerWidth - width) / 2, top: (window.innerHeight - height) / 2, width, height },
    };
}
export default function FlipCardModal() {
    const trigger = useRef<HTMLButtonElement>(null);
    const [open, setOpen] = useState(false);
    const [flipped, setFlipped] = useState(true);
    const [bounds, setBounds] = useState<Bounds | null>(null);
    const reduce = useReducedMotion() === true;
    const close = () => setOpen(false);
    const show = () => {
        if (!trigger.current)
            return;
        setBounds(measure(trigger.current));
        setFlipped(true);
        setOpen(true);
    };
    return (<>
      <div className="art:w-full art:max-w-[18rem]">
        <div>
          <button ref={trigger} onClick={show} disabled={open} type="button" aria-label="Open flip card" aria-haspopup="dialog" aria-expanded={open} aria-controls="flip-card-modal-gallery-room" className="art:relative art:aspect-[4/5] art:w-full art:cursor-pointer art:overflow-hidden art:rounded-3xl art:border art:border-border art:bg-background art:text-left art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:disabled:cursor-default">
            <Front />
          </button>
        </div>
      </div>
      <AnimatePresence>
        {open && bounds && (<Dialog static open onClose={close} className="art:relative art:z-[100]">
            <MotionConfig transition={reduce ? { duration: 0 } : { duration: 0.24, ease: ARTEMIS_EASE_OUT }}>
              <DialogBackdrop as={motion.div} className="art:fixed art:inset-0 art:bg-foreground/10 art:backdrop-blur-xl" initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}/>
            </MotionConfig>
            <div id="flip-card-modal-gallery-room" className="art:pointer-events-none art:fixed art:inset-0 art:z-[101] art:[perspective:1400px]">
              <MotionConfig transition={reduce ? { duration: 0 } : OPEN}>
                <DialogPanel as={motion.div} className="art:pointer-events-auto art:fixed art:touch-manipulation art:[transform-style:preserve-3d] art:outline-none art:[will-change:transform,left,top,width,height]" initial={reduce ? false : { ...bounds.origin, rotateY: 0 }} animate={{ ...bounds.target, rotateY: flipped ? 180 : 0 }} exit={{ ...bounds.origin, rotateY: 0, transition: reduce ? { duration: 0 } : CLOSE }}>
                  <div aria-hidden={flipped} inert={flipped} className="art:absolute art:inset-0 art:overflow-hidden art:rounded-3xl art:border art:border-border art:bg-background art:[backface-visibility:hidden] art:[transform:translateZ(1px)]">
                    <button type="button" aria-label="Show the back of this card" onClick={() => setFlipped(true)} className={FLIP}/>
                    <div className={SURFACE}><Front /></div>
                    <Close onClose={close}/>
                  </div>
                  <div aria-hidden={!flipped} inert={!flipped} className="art:absolute art:inset-0 art:overflow-hidden art:rounded-3xl art:border art:border-border art:bg-background art:[backface-visibility:hidden] art:[transform:rotateY(180deg)_translateZ(1px)]">
                    <button type="button" aria-label="Show the front of this card" onClick={() => setFlipped(false)} className={FLIP}/>
                    <div className={SURFACE}><Back /></div>
                    <Close onClose={close} autoFocus/>
                  </div>
                </DialogPanel>
              </MotionConfig>
            </div>
          </Dialog>)}
      </AnimatePresence>
    </>);
}

"use client";
// @zeus-internal
import { ArrowUpRight, X } from "lucide-react";
export function Front() {
    return (<div className="art:relative art:h-full art:w-full">
              <img src="/assets/artemis/abc0c093fee16ad475a0.avif" alt="Minimal gallery room washed in natural light" width="1100" height="1375" loading="lazy" className="art:h-full art:w-full art:object-cover"/>
              <span className="art:absolute art:inset-x-3 art:bottom-3 art:rounded-2xl art:border art:border-border/60 art:bg-background/55 art:p-4 art:text-foreground art:backdrop-blur-xl art:backdrop-saturate-150 art:sm:inset-x-4 art:sm:bottom-4 art:sm:p-5">
                <span className="art:block art:font-medium art:text-muted-foreground art:text-xs art:sm:text-sm">
                  {"Private collection"}
                </span>
                <span className="art:mt-2 art:block art:font-medium art:text-xl art:sm:text-2xl">
                  {"The light room"}
                </span>
                <span className="art:mt-2 art:block art:text-muted-foreground art:text-xs art:sm:text-sm">
                  {"Click to open the story"}
                </span>
              </span>
            </div>);
}
export function Back() {
    return (<div className="art:relative art:h-full art:w-full">
      <img src="/assets/artemis/4731feb50ab655cdf945.avif" alt="Sculptural stone interior detail" width="1100" height="1375" loading="lazy" className="art:h-full art:w-full art:object-cover"/>
      <span className="art:absolute art:inset-x-3 art:bottom-3 art:rounded-2xl art:border art:border-border/60 art:bg-background/60 art:p-4 art:text-foreground art:backdrop-blur-xl art:backdrop-saturate-150 art:sm:inset-x-4 art:sm:bottom-4 art:sm:p-5">
        <span className="art:block art:font-medium art:text-xl art:sm:text-2xl">Designed around stillness</span>
        <span className="art:mt-2 art:block art:text-muted-foreground art:text-xs art:leading-5 art:sm:mt-3 art:sm:text-sm art:sm:leading-6">Natural materials and measured openings shape a calm place for art, conversation, and changing light</span>
        <a href="#light-room" className="art:mt-4 art:inline-flex art:h-10 art:items-center art:gap-2 art:rounded-full art:border art:border-border art:bg-background art:px-4 art:font-medium art:text-xs art:outline-none art:transition-colors art:hover:bg-muted art:focus-visible:ring-2 art:focus-visible:ring-ring art:sm:mt-5 art:sm:text-sm">View the project<ArrowUpRight className="art:size-4"/></a>
      </span>
    </div>);
}
export function Close({ onClose, autoFocus = false }: {
    onClose: () => void;
    autoFocus?: boolean;
}) {
    return (<button type="button" data-autofocus={autoFocus || undefined} aria-label="Close flip card" onClick={onClose} className="art:absolute art:top-4 art:right-4 art:z-40 art:grid art:size-10 art:place-items-center art:rounded-full art:border art:border-border/60 art:bg-background/55 art:text-foreground art:outline-none art:backdrop-blur-xl art:backdrop-saturate-150 art:transition-colors art:hover:bg-background/75 art:focus-visible:ring-2 art:focus-visible:ring-ring"><X className="art:size-4"/></button>);
}
